// TH16 v1.00a type 8 = rice (etSprite(0, 8, 6) in GirlA03_at:621).
// Approved alias of the identical TH18 type slot; see bullet-types.md.
const TH16_RICE: int = 480;

// TH16 v1.00a st04 MainSub01 wave (th16_s4_w03).
// Source: st04.ecl.txt MainSub01:1463-1510, GirlA03:582-590, GirlA03F:592-613,
// GirlA03_at:615-668. Bullet: type 8 (TH16_RICE) color 6.

const TIME_LIMIT: int = 1930;
const OPENING_BUFFER: int = 120;

// GirlA03_at:631-643 single aimed lane. etEx(type 2, a=1) is the birth ANIM: the
// animation itself is omitted, but its entry shift position -= 4*velocity stays,
// so spawn 4*speed behind the muzzle along the bullet angle.
sub shot(a: angle, sp: fx) {
    var bx: fx = $self_x - 4fx * sp * cos(a);
    var by: fx = $self_y - 4fx * sp * sin(a);
    _ = fire(TH16_RICE, 6, bx, by, sp, a, none, none);
}

// etAim(0) one lane, etCount(0, 1, layers), etSpeed(s0, 2.2): layer q gets
// s0 + (2.2-s0)*q/(layers-1), same angle for both layers (etAngle spread 0).
sub round_shots(alpha: int, layers: int, v0: fx) {
    var aim: angle = aim_player();
    var a: angle = aim + (alpha as angle);
    shot(a, v0);
    if layers > 1 { shot(a, 2.2fx); }
}

// GirlA03_at:617-667. wait(60); three rounds (A=3); each round samples one
// RANDF2-spread angle, then B bursts of etOn + wait(3), then the burst gap.
async sub girl_shot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var v0: fx = 1.5fx;
    var bursts: int = 1;
    var gap: int = 140;
    var layers: int = 1;
    if rank == 1 { v0 = 2.8fx; bursts = 3; gap = 70; }
    else if rank >= 2 { v0 = 3.5fx; bursts = 3; gap = 35; }
    if rank >= 3 { layers = 2; }
    for r in 0..3 {
        var ra: int = rand(65536);                      // %RANDF2 at GirlA03_at_480
        var alpha: int = ((ra - 32768) * 1820) / 32768; // * 0.17453292 rad = 10deg
        for b in 0..bursts {
            round_shots(alpha, layers, v0);
            wait(3);
        }
        wait(gap);
    }
}

// GirlA03:582-590 + GirlA03F:592-613. Spawn fade sets source flags 3 for 60 frames
// (GirlA01_color:453-462); only the body-gate part is expressible here.
async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(12fx);                       // setHurtbox(24,24): 24*0.5
    set_hitbox(8fx);                         // setHitbox(16,16): 16*0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spawn girl_shot();
    move_vel(0, 90deg, 0.5fx, EASE_LINEAR);  // moveVel(pi/2, 0.5)
    wait(60);                                // +60: //60
    set_enemy_flag(ENEMY_NO_BODY, 0);
    move_vel(60, 90deg, 2fx, EASE_LINEAR);   // moveVelTime(60, 0, pi/2, 2.0)
    wait(80);                                // +80: //140
    var ra: int = rand(65536);               // pi/2 + RANDF2*0.5235988 (sampled here, used at 220)
    var off: int = ((ra - 32768) * 5461) / 32768;
    var turn: angle = 90deg + (off as angle);
    wait(80);                                // +80: //220
    move_vel(60, turn, -2fx, EASE_LINEAR);   // moveVelTime(60, 0, [-1.0f], -2.0f)
    loop { wait(1000); }                     // GirlA03F_408/428 wait(1000) loop
}

// MainSub01:1470-1471 etc. enmCreate("GirlA03", A, 32.0f, 200, 1000, 1) x2.
sub spawn_pair(x: fx, dx: fx) {
    _ = spawn_enemy(x, 32fx, 200, 0, 1000, 0, girl_main);
    _ = spawn_enemy(x + dx, 32fx, 200, 0, 1000, 0, girl_main);
}

// MainSub01:1465-1508: four groups of 10 pairs, A step 20, group gaps 130/100/60.
async sub pattern() {
    wait(OPENING_BUFFER);
    for k1 in 0..10 {                        // group 1: A=180 -> -20 step, partner A-180
        spawn_pair(((180 - 20 * k1) as fx), -180fx);
        wait(20);
    }
    wait(130);
    for k2 in 0..10 {                        // group 2: same sweep (MainSub01:1476-1486)
        spawn_pair(((180 - 20 * k2) as fx), -180fx);
        wait(20);
    }
    wait(100);
    for k3 in 0..10 {                        // group 3: A=-180 -> +20 step, partner A+180
        spawn_pair(((-180 + 20 * k3) as fx), 180fx);
        wait(20);
    }
    wait(60);
    for k4 in 0..10 {                        // group 4: same sweep (MainSub01:1498-1508)
        spawn_pair(((-180 + 20 * k4) as fx), 180fx);
        wait(20);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
